# Build test input
test_input = [[8 for _ in range(8)] for _ in range(30)]
for pos in [(1,6), (3,7), (5,0), (5,7), (9,2), (12,2), (12,4), (17,6), (20,7), (21,5)]:
    test_input[pos[0]][pos[1]] = 7

# Apply transformation: fill cells between markers (7s) with 3s
output = [[8 for _ in range(8)] for _ in range(30)]

# Preserve markers
for pos in [(1,6), (3,7), (5,0), (5,7), (9,2), (12,2), (12,4), (17,6), (20,7), (21,5)]:
    output[pos[0]][pos[1]] = 7

# Fill rows between consecutive 7s
for r in range(30):
    rows_7 = sorted([c for c in range(8) if test_input[r][c] == 7])
    for i in range(len(rows_7) - 1):
        for c in range(rows_7[i] + 1, rows_7[i+1]):
            output[r][c] = 3

# Fill columns between consecutive 7s  
for c in range(8):
    cols_7 = sorted([r for r in range(30) if test_input[r][c] == 7])
    for i in range(len(cols_7) - 1):
        for r in range(cols_7[i] + 1, cols_7[i+1]):
            output[r][c] = 3

print("Output grid:")
for row in output:
    print(' '.join(map(str, row)))
